add_action( 'woocommerce_payment_complete', 'perfectpixel_tag_purchased_products' );
add_action( 'woocommerce_order_status_completed', 'perfectpixel_tag_purchased_products' );

function perfectpixel_tag_purchased_products( $order_id ) {
	$order = wc_get_order( $order_id );
	if ( ! $order || $order->get_meta( '_perfectpixel_products_tagged' ) ) {
		return;
	}
	foreach ( $order->get_items() as $item ) {
		$product_id = $item->get_product_id();
		if ( $product_id ) {
			wp_set_object_terms( $product_id, '{{purchased_tag}}', 'product_tag', true );
		}
	}
	$order->update_meta_data( '_perfectpixel_products_tagged', 1 );
	$order->save();
}
